-- Transactional: Normalized for consistency
CREATE TABLE orders (order_id UUID PRIMARY KEY, user_id UUID, status VARCHAR(20));

-- Reporting: Denormalized for OLAP performance
CREATE TABLE fact_sales (
    date_key INT, 
    product_key INT, 
    total_amount DECIMAL(19,4)
) WITH (format = 'PARQUET', partitioning = 'date_key');
